for _lang, _extra in AI_TEXTS.items():
    TEXTS[_lang].update(_extra)

for _lang, _texts in TEXTS.items():
    _texts.update({f'class_{k}': v for k, v in CLASS_NAMES[_lang].items()})
    _texts.update({f'race_{k}': v for k, v in RACE_NAMES[_lang].items()})
    for _klass, _names in SPEC_NAMES[_lang].items():
        _texts.update({f'spec_{_klass}_{i}': name for i, name in enumerate(_names)})


def texts(lang: str) -> dict:
    """All panel texts of a language (English for anything missing)."""
    merged = dict(TEXTS['en'])
    merged.update(TEXTS.get(lang, {}))
    return merged
